mapper.data:
{
  "model": "anthropic/claude-sonnet-4-6",
  "messages": [
    {
      "role": "user",
      "content": "Write a personalized AI readiness audit report for {{2.business_name}}, a {{2.industry}} business. Their score is {{2.readiness_score}}/100. They handle {{2.monthly_leads}} leads/month. After-hours handling: {{2.after_hours_handling}}. Biggest pain point: {{2.pain_point}}. Write 3 short paragraphs: (1) Their score and what it means, (2) Their #1 automation opportunity, (3) A specific recommendation. Keep it under 200 words. Warm and actionable. Do not mention any AI company names or vendor names."
    }
  ],
  "max_tokens": 400,
  "temperature": 0.7
}

{
  "from": "{{env.RESEND_FROM_NAME}} <{{env.RESEND_FROM_ADDRESS}}>",
  "to": ["{{2.email}}"],
  "subject": "Your AI Readiness Score: {{2.readiness_score}}/100 — {{2.business_name}}",
  "html": "<!DOCTYPE html><html><head><meta charset='UTF-8'><style>body{font-family:Arial,sans-serif;background:#f9f9f9;margin:0;padding:0;}table{border-collapse:collapse;}.wrapper{max-width:600px;margin:0 auto;background:#ffffff;border-radius:8px;overflow:hidden;}.header{background:#1a1a2e;padding:32px 40px;}.header h1{color:#ffffff;margin:0;font-size:22px;font-weight:600;}.score-box{background:#fff7ed;border:2px solid #f97316;border-radius:12px;padding:24px 32px;text-align:center;margin:32px 40px 0 40px;}.score-box .score-label{font-size:14px;color:#92400e;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px;}.score-box .score-value{font-size:64px;font-weight:800;color:#f97316;line-height:1;}.score-box .score-denom{font-size:24px;color:#f97316;font-weight:600;}.body-content{padding:32px 40px;color:#374151;font-size:15px;line-height:1.7;}.cta-wrapper{text-align:center;padding:8px 40px 40px 40px;}.cta-button{display:inline-block;background:#f97316;color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:700;letter-spacing:0.5px;}.footer{background:#f3f4f6;padding:20px 40px;text-align:center;font-size:12px;color:#9ca3af;}</style></head><body><table width='100%' cellpadding='0' cellspacing='0'><tr><td><div class='wrapper'><div class='header'><h1>Your AI Readiness Audit</h1></div><div class='score-box'><div class='score-label'>Your Score</div><div><span class='score-value'>{{2.readiness_score}}</span><span class='score-denom'>/100</span></div></div><div class='body-content'><p>Hi {{2.firstname}},</p><p>Thank you for completing the AI Readiness Audit for <strong>{{2.business_name}}</strong>. Here is your personalized report:</p><p style='white-space:pre-line;'>{{3.data.choices[0].message.content}}</p></div><div class='cta-wrapper'><a href='{{env.CALENDLY_LINK}}' class='cta-button'>Book Your Free Strategy Call</a></div><div class='footer'><p>You are receiving this because you requested a free audit at our website.<br>If you have questions, simply reply to this email.</p></div></div></td></tr></table></body></html>"
}

{
  "from": "{{env.CWI_ALERT_FROM_ADDRESS}}",
  "to": ["{{env.ADMIN_EMAIL}}"],
  "subject": "New Free Audit Lead: {{2.business_name}} scored {{2.readiness_score}}/100",
  "html": "<h2>New Free Audit Submission</h2><table style='border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;'><tr><td style='padding:6px 12px;font-weight:bold;'>Business Name</td><td style='padding:6px 12px;'>{{2.business_name}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Contact Name</td><td style='padding:6px 12px;'>{{2.contact_name}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Email</td><td style='padding:6px 12px;'>{{2.email}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Phone</td><td style='padding:6px 12px;'>{{2.phone}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Industry</td><td style='padding:6px 12px;'>{{2.industry}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Monthly Leads</td><td style='padding:6px 12px;'>{{2.monthly_leads}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>After-Hours Handling</td><td style='padding:6px 12px;'>{{2.after_hours_handling}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Pain Point</td><td style='padding:6px 12px;'>{{2.pain_point}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;color:#f97316;'>Readiness Score</td><td style='padding:6px 12px;font-weight:bold;color:#f97316;font-size:18px;'>{{2.readiness_score}}/100</td></tr></table><br><p><a href='https://app.hubspot.com/contacts/{{env.HUBSPOT_PORTAL_ID}}/contact/{{5.data.id}}' style='background:#1a1a2e;color:#ffffff;padding:10px 24px;text-decoration:none;border-radius:6px;font-weight:bold;'>View in HubSpot</a></p>"
}

{
  "from": "{{env.CWI_ALERT_FROM_ADDRESS}}",
  "to": ["{{env.ADMIN_EMAIL}}"],
  "subject": "[ERROR] Scenario P Free Audit Handler Failed",
  "html": "<h2 style='color:#dc2626;'>Scenario P Error</h2><p>The Free AI Readiness Audit Handler (Scenario P) encountered an error and did not complete successfully.</p><table style='border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;'><tr><td style='padding:6px 12px;font-weight:bold;'>Error Message</td><td style='padding:6px 12px;'>{{error.message}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Failed Module</td><td style='padding:6px 12px;'>{{error.module}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Time</td><td style='padding:6px 12px;'>{{formatDate(now; 'MMMM D, YYYY h:mm A'; 'America/New_York')}} ET</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Business Name</td><td style='padding:6px 12px;'>{{1.business_name}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Lead Email</td><td style='padding:6px 12px;'>{{1.email}}</td></tr></table><p>Please check the Make.com execution log and follow up with this lead manually if needed.</p>"
}
